  queue.enqueue('x', 1);
  queue.compact();
  queue.enqueue('x', 2);
  queue.compact();
  queue.enqueue('x', 3);
  queue.close();
  const reopened = openQueue(dir, { clock });
  assert.equal(reopened.stats().total, 3);
  assert.equal(new Set(reopened.listJobs().map((j) => j.id)).size, 3);
});

