  assert.equal(openQueue(dir, options).stats().total, 1);
});

test('a log far bigger than one read chunk, with records bigger than it, loads whole', (t) => {
  const { dir, options } = setup(t, { compactAfterBytes: 0 });
  const queue = openQueue(dir, options);
  const jobs = Array.from({ length: 300 }, (_, n) => ({ type: 'x', payload: { n, pad: 'p'.repeat(20_000) } }));
  queue.enqueueMany(jobs);
  queue.enqueue('x', { huge: 'h'.repeat(3 * 1024 * 1024) });
  queue.enqueue('x', 'last');
  queue.close();
  assert.ok(fs.statSync(path.join(dir, 'wal.log')).size > 8 * 1024 * 1024);

  const reopened = openQueue(dir, options);
  assert.equal(reopened.stats().total, 302);
  assert.equal(reopened.stats().tornTailsDropped, 0);
  reopened.compact();
  assert.equal(reopened.stats().total, 302);
  reopened.close();
  assert.equal(openQueue(dir, options).stats().total, 302);
});

test('a state too big for one frame compacts into several and reloads', (t) => {
