  queue.fail(id, first.token, 'dead now');
  queue.requeueDead(id);
  queue.compact();
  const second = queue.claim('w');
  assert.ok(second.token > first.token);
  assert.throws(() => queue.complete(id, first.token, 'late'), { name: 'StaleLeaseError' });
});

test('compaction works with a reader holding the log open, and again afterwards', (t) => {
  const { dir, options, log } = setup(t);
