  queue.enqueue('x', 1);
  const reader = fs.openSync(log, 'r');
  try {
    queue.compact();
    queue.enqueue('x', 2);
    queue.compact();
  } finally {
    fs.closeSync(reader);
  }
  queue.compact();
  queue.close();
