    const image =
      point === 'wal.after-create'
        ? crashAt(t, dir, point, () => openQueue(dir, options))
        : crashAt(t, dir, point, () => {
            queue = openQueue(dir, options);
            queue.enqueue('x', 1);
            queue.compact();
          });
    const opened = openQueue(image, options);
    if (point !== 'wal.after-create') assert.equal(opened.stats().total, 1, point);
    opened.enqueue('x', 2);
    opened.close();
  }
});

